1. import { CopilotClient, type CopilotSession, type SectionOverride, type SystemMessageConfig, type Tool } from "@github/copilot-sdk";
2. import { ManagedSession } from "./managed-session.js";
3. import type { SessionStateStore } from "./session-store.js";
4. import { SESSION_STATE_MISSING_PREFIX, type AbortTurnResult, type ManagedSessionConfig, type SerializableSessionConfig } from "./types.js";
5. import type { ModelProviderRegistry } from "./model-providers.js";
6. import { createFactTools } from "./facts-tools.js";
7. import { createGraphTools } from "./graph-tools.js";
8. import { createInspectTools } from "./inspect-tools.js";
9. import { pinToolsNeverDefer } from "./tool-pinning.js";
10. import type { SessionCatalog } from "./cms.js";
11. import { SYSTEM_USER_PRINCIPAL } from "./cms.js";
12. import type { FactStore } from "./facts-store.js";
13. import { isEnhancedFactStore } from "./facts-store.js";
14. import type { GraphStore } from "./graph-store.js";
15. import { buildKnowledgePromptBlocks, loadKnowledgeIndexFromFactStore, buildEnhancedRetrievalPromptBlock, buildGraphReaderPromptBlock } from "./knowledge-index.js";
16. import { composeStructuredSystemMessage, extractPromptContent, mergePromptSections } from "./prompt-layering.js";
17. import { buildPromptLayersEventPayload, type PromptLayerDescriptor } from "./prompt-layers.js";
18. import { approvePermissionForSession } from "./permissions.js";
19. import { readSnapshotMarker, supportsVersionedSnapshots, writeSnapshotMarker } from "./snapshot-protocol.js";
20. import fs from "node:fs";
21. import path from "node:path";
22. import os from "node:os";
23. 
24. const DEFAULT_SESSION_STATE_DIR = path.join(os.homedir(), ".copilot", "session-state");
25. const DEHYDRATE_STORE_MAX_RETRIES = 1;
26. const DEHYDRATE_STORE_RETRY_BASE_DELAY_MS = 0;
27. const SESSION_LOCK_BACKOFF_MS = [5_000, 10_000, 20_000] as const;
28. const SESSION_LOCK_MAX_WAIT_MS = 120_000;
29. export const SESSION_LOCK_ACQUIRE_TIMEOUT_CODE = "PILOTSWARM_SESSION_LOCK_ACQUIRE_TIMEOUT";
30. 
31. export class SessionLockAcquireTimeoutError extends Error {
32.     readonly code = SESSION_LOCK_ACQUIRE_TIMEOUT_CODE;
33.     readonly sessionId: string;
34.     readonly operation: string;
35.     readonly waitedMs: number;
36. 
37.     constructor(sessionId: string, operation: string, waitedMs: number) {
38.         super(`can't acquire session lock for session ${sessionId} while running ${operation} after ${waitedMs}ms`);
39.         this.name = "SessionLockAcquireTimeoutError";
40.         this.sessionId = sessionId;
41.         this.operation = operation;
42.         this.waitedMs = waitedMs;
43.     }
44. }
45. 
46. export function isSessionLockAcquireTimeoutError(error: unknown): error is SessionLockAcquireTimeoutError {
47.     return Boolean(error && typeof error === "object" && (error as any).code === SESSION_LOCK_ACQUIRE_TIMEOUT_CODE);
48. }
49. 
50. function sleep(ms: number): Promise<void> {
51.     return new Promise((resolve) => setTimeout(resolve, ms));
52. }
53. 
54. function normalizeError(error: unknown): Error {
55.     if (error instanceof Error) return error;
56.     return new Error(String(error));
57. }
58. 
59. type SessionTraceWriter = (message: string) => void;
60. 
61. function emitSessionManagerTrace(
62.     sessionId: string,
63.     message: string,
64.     options?: { trace?: SessionTraceWriter; level?: "info" | "warn" },
65. ): void {
66.     const line = `[SessionManager] session=${sessionId} orch=session-${sessionId} ${message}`;
67.     if (typeof options?.trace === "function") {
68.         options.trace(line);
69.         return;
70.     }
71.     if (options?.level === "warn") {
72.         console.warn(line);
73.         return;
74.     }
75.     console.info(line);
76. }
77. 
78. function isMissingDehydrateSnapshotError(error: unknown): boolean {
79.     const message = error instanceof Error ? error.message : String(error ?? "");
80.     return /Session state directory not ready during dehydrate/i.test(message);
81. }
82. 
83. /** Worker-level defaults — applied to every session. */
84. export interface WorkerDefaults {
85.     frameworkBasePrompt?: string;
86.     frameworkBaseToolNames?: string[];
87.     appDefaultPrompt?: string;
88.     appDefaultToolNames?: string[];
89.     /** Backward-compatible alias for older code paths/tests. */
90.     systemMessage?: string;
91.     /** Raw prompt lookup for named and system agents bound directly to sessions. */
92.     agentPromptLookup?: Record<string, { prompt: string; kind: "app-agent" | "app-system-agent" | "pilotswarm-system-agent"; descriptor?: import("./prompt-layers.js").PromptLayerDescriptor }>;
93.     /** Descriptor for the PilotSwarm framework base layer (from system default.agent.md). */
94.     frameworkBaseDescriptor?: import("./prompt-layers.js").PromptLayerDescriptor;
95.     /** Descriptor for the app default layer (from app default.agent.md or inline config). */
96.     appDefaultDescriptor?: import("./prompt-layers.js").PromptLayerDescriptor;
97.     /** Skill directories to pass to the Copilot SDK. */
98.     skillDirectories?: string[];
99.     /** Custom agents to pass to the Copilot SDK. */
100.     customAgents?: Array<{ name: string; description?: string; prompt: string; tools?: string[] | null; skills?: string[]; mcpServers?: Record<string, any> }>;
101.     /**
102.      * Deployment MCP catalog (merged `.mcp.json` map). NOT applied to
103.      * sessions wholesale — a session receives exactly its bound agent's
104.      * resolved map from `agentMcpServers` (capability-profiles Phase 1).
105.      */
106.     mcpServers?: Record<string, any>;
107.     /** Resolved per-agent MCP server maps, keyed by bound agent name. */
108.     agentMcpServers?: Record<string, Record<string, any>>;
109.     /**
110.      * Resolved base MCP map applied to EVERY session: base (default) agent
111.      * opt-ins plus direct worker-config servers (legacy semantics).
112.      */
113.     baseMcpServers?: Record<string, any>;
114.     /**
115.      * @deprecated Use `modelProviders` instead. Kept for backwards compatibility.
116.      * Custom LLM provider config (BYOK). Passed to every session.
117.      */
118.     provider?: {
119.         type?: "openai" | "azure" | "anthropic";
120.         baseUrl: string;
121.         apiKey?: string;
122.         azure?: { apiVersion?: string };
123.     };
124.     /** Multi-provider model registry. Takes precedence over `provider`. */
125.     modelProviders?: ModelProviderRegistry;
126.     /** Wall-clock turn cap in ms. 0 = no cap; undefined = 20-minute default. */
127.     turnTimeoutMs?: number;
128.     /** Turn inactivity watchdog in ms. 0 = disabled; undefined = 5-minute default. */
129.     turnInactivityTimeoutMs?: number;
130. }
131. 
132. function buildEffectivePromptLayers(workerDefaults: WorkerDefaults, config: SerializableSessionConfig): PromptLayerDescriptor[] {
133.     const boundAgentName = config.boundAgentName;
134.     const layerKind = config.promptLayering?.kind ?? (boundAgentName ? "app-agent" : undefined);
135.     const isPilotSwarmSystemAgent = layerKind === "pilotswarm-system-agent";
136.     const layers: PromptLayerDescriptor[] = [];
137.     if (workerDefaults.frameworkBaseDescriptor) layers.push(workerDefaults.frameworkBaseDescriptor);
138.     if (!isPilotSwarmSystemAgent && workerDefaults.appDefaultDescriptor) layers.push(workerDefaults.appDefaultDescriptor);
139.     if (boundAgentName) {
140.         const agentDescriptor = workerDefaults.agentPromptLookup?.[boundAgentName]?.descriptor;
141.         if (agentDescriptor) layers.push(agentDescriptor);
142.     }
143.     return layers;
144. }
