146. /**
147.  * SessionManager — singleton per worker node.
148.  * Owns session lifecycle, wraps CopilotClient.
149.  *
150.  * Three ways a session appears:
151.  *   1. Brand new → createSession
152.  *   2. Same node, still warm → getSession returns it
153.  *   3. Post-hydration → local files exist → resumeSession
154.  *
155.  * @internal
156.  */
157. export class SessionManager {
158.     private clients = new Map<string, CopilotClient>();
159.     /**
160.      * Backward-compat accessor for the default-token CopilotClient.
161.      *
162.      * The internal multi-client pool is keyed by GitHub Copilot token (so
163.      * per-user keys can override `GITHUB_TOKEN` for a specific session).
164.      * Tests that predate the pool — and a couple of internal call sites
165.      * that assume a single shared client — still read or assign
166.      * `manager.client = fakeClient` to inject a stub. Honor that by
167.      * populating both the empty-key slot AND the worker-default token
168.      * slot so `ensureClient()` returns the fake whether or not the
169.      * default `GITHUB_TOKEN` was set on the constructor.
170.      */
171.     get client(): CopilotClient | undefined {
172.         return this.clients.get("") ?? this.clients.get(this.githubToken || "");
173.     }
174.     set client(value: CopilotClient | undefined) {
175.         if (value) {
176.             this.clients.set("", value);
177.             if (this.githubToken) this.clients.set(this.githubToken, value);
178.         } else {
179.             this.clients.delete("");
180.             if (this.githubToken) this.clients.delete(this.githubToken);
181.         }
182.     }
183.     private sessions = new Map<string, ManagedSession>();
184. 
185.     /** Live in-memory session count — worker-registry health reporting. */
186.     get activeSessionCount(): number {
187.         return this.sessions.size;
