130.  * boundaries only — a JSONL record is never divided — and a single line that
131.  * exceeds the limit on its own becomes its own oversized chunk rather than
132.  * being silently dropped (the store will reject it and the caller reports a
133.  * real failure instead of losing a message).
134.  */
135. export function chunkArchiveLines(lines: string[], maxBytes: number): string[] {
136.     const chunks: string[] = [];
137.     let current: string[] = [];
138.     let currentBytes = 0;
139.     for (const line of lines) {
140.         const lineBytes = Buffer.byteLength(line, "utf8") + 1; // + newline
141.         if (current.length > 0 && currentBytes + lineBytes > maxBytes) {
142.             chunks.push(current.join("\n") + "\n");
143.             current = [];
144.             currentBytes = 0;
145.         }
146.         current.push(line);
147.         currentBytes += lineBytes;
148.     }
149.     if (current.length > 0) chunks.push(current.join("\n") + "\n");
150.     // Always at least one chunk. An empty transcript used to yield zero
151.     // chunks, so runRegenArchive returned an archiveArtifactId naming an
152.     // artifact it never uploaded and the distiller's first read 404'd.
153.     if (chunks.length === 0) chunks.push("");
154.     return chunks;
155. }
