1. /**
2.  * Model provider registry — loads and resolves multi-provider LLM configuration.
3.  *
4.  * Reads a `model_providers.json` file that defines multiple LLM providers
5.  * (GitHub Copilot, Azure OpenAI, OpenAI, Anthropic, local/Ollama) each with
6.  * their own endpoints, API keys, and available models.
7.  *
8.  * Models are identified by normalized strings: `provider:model`
9.  * (e.g. `github-copilot:claude-opus-4`, `anthropic:claude-sonnet-4-6`).
10.  *
11.  * Secrets use the `env:VAR_NAME` syntax to reference environment variables
12.  * so keys stay in `.env` files while provider config stays in JSON.
13.  *
14.  * @module
15.  */
16. 
17. import fs from "node:fs";
18. import path from "node:path";
19. 
20. // ─── Types ───────────────────────────────────────────────────────
21. 
22. /** Reasoning effort levels accepted by the Copilot CLI. */
23. export type ReasoningEffort = "none" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max";
24. 
25. /**
26.  * Context-window tier accepted by the Copilot SDK (CLI 1.0.6x+).
27.  * "default" is the smaller/cheaper window; "long_context" pins the session to
28.  * the model's long-context tier (larger window, higher token cost).
29.  */
30. export type ContextTier = "default" | "long_context";
31. 
32. /** A model entry within a provider. */
33. export interface ModelEntry {
34.     /** Model name (deployment name for Azure). */
35.     name: string;
36.     /** Short description of when to use this model. */
37.     description?: string;
38.     /** Relative cost tier. */
39.     cost?: "low" | "medium" | "high";
40.     /** Optional reasoning effort levels exposed in the UI for this model. */
41.     supportedReasoningEfforts?: ReasoningEffort[];
42.     /** Optional default reasoning effort when creating sessions. */
43.     defaultReasoningEffort?: ReasoningEffort;
44.     /** Optional context-window tiers exposed in the UI for this model. */
45.     supportedContextTiers?: ContextTier[];
46.     /** Optional default context tier when creating sessions (prefer "default", the smaller window). */
47.     defaultContextTier?: ContextTier;
48.     /** Optional token capacity for each supported context-window tier. */
49.     contextWindowSizes?: Partial<Record<ContextTier, number>>;
50. }
51. 
52. /** A single provider entry in model_providers.json. */
53. export interface ModelProviderConfig {
54.     /** Unique identifier for this provider (e.g. "azure-openai", "github-copilot"). */
55.     id: string;
56.     /** Provider type. */
57.     type: "github" | "azure" | "openai" | "anthropic";
58.     /**
59.      * GitHub token (type=github only). Supports `env:VAR_NAME` syntax.
60.      * When type=github, the SDK uses the Copilot API — no baseUrl needed.
61.      */
62.     githubToken?: string;
63.     /**
64.      * API endpoint URL. Required for non-github providers.
65.      * For Azure: base URL without /deployments/ (e.g. https://resource.openai.azure.com/openai)
66.      * For OpenAI: https://api.openai.com/v1
67.      * For Anthropic: https://api.anthropic.com
68.      */
69.     baseUrl?: string;
70.     /** API key. Supports `env:VAR_NAME` syntax. */
71.     apiKey?: string;
72.     /** Azure API version (type=azure only). Defaults to "2024-10-21". */
73.     apiVersion?: string;
74.     /** Available models. Can be plain strings (legacy) or ModelEntry objects with descriptions. */
75.     models: (string | ModelEntry)[];
76. }
77. 
78. /** Top-level model_providers.json schema. */
79. export interface ModelProvidersFile {
80.     providers: ModelProviderConfig[];
81.     /** Default model in `provider:model` format. */
82.     defaultModel?: string;
83. }
84. 
85. /** A fully-resolved model descriptor for display and selection. */
86. export interface ModelDescriptor {
87.     /** Normalized ID: `provider:model` */
88.     qualifiedName: string;
89.     /** Raw model name (for SDK config). */
90.     modelName: string;
91.     /** Provider ID. */
92.     providerId: string;
93.     /** Provider type. */
94.     providerType: "github" | "azure" | "openai" | "anthropic";
95.     /** Short description of when to use this model. */
96.     description?: string;
97.     /** Relative cost tier. */
98.     cost?: "low" | "medium" | "high";
99.     /** Optional reasoning effort levels exposed in the UI for this model. */
100.     supportedReasoningEfforts?: ReasoningEffort[];
101.     /** Optional default reasoning effort when creating sessions. */
102.     defaultReasoningEffort?: ReasoningEffort;
103.     /** Optional context-window tiers exposed in the UI for this model. */
104.     supportedContextTiers?: ContextTier[];
105.     /** Optional default context tier when creating sessions. */
106.     defaultContextTier?: ContextTier;
107.     /** Optional token capacity for each supported context-window tier. */
108.     contextWindowSizes?: Partial<Record<ContextTier, number>>;
109. }
110. 
111. /** Resolved provider info for a specific model — ready to use. */
112. export interface ResolvedProvider {
113.     /** The provider ID from model_providers.json. */
114.     providerId: string;
115.     /** Provider type. */
116.     type: "github" | "azure" | "openai" | "anthropic";
117.     /** Raw model name (for SDK config). */
118.     modelName: string;
119.     /** Resolved GitHub token (type=github only). */
120.     githubToken?: string;
121.     /**
122.      * Copilot SDK ProviderConfig — passed to SessionConfig.provider.
123.      * Undefined for type=github (uses githubToken instead).
124.      */
125.     sdkProvider?: {
126.         type: "openai" | "azure" | "anthropic";
127.         baseUrl: string;
128.         apiKey?: string;
129.         azure?: { apiVersion?: string };
130.     };
131. }
132. 
133. // ─── Registry ────────────────────────────────────────────────────
134. 
135. /**
136.  * ModelProviderRegistry — loaded once at worker startup.
137.  * Maps normalized `provider:model` strings to their provider configs.
138.  */
139. export class ModelProviderRegistry {
140.     private providers: ModelProviderConfig[];
141.     /** Qualified name → ModelDescriptor */
142.     private descriptors = new Map<string, ModelDescriptor>();
143.     /** Qualified name → ModelProviderConfig */
144.     private qualifiedToProvider = new Map<string, ModelProviderConfig>();
145.     /** Bare model name → first matching qualified name (for backwards compat). */
146.     private bareToQualified = new Map<string, string>();
147.     private _defaultModel: string | undefined;
148.     private _allDescriptors: ModelDescriptor[] = [];
149. 
150.     constructor(config: ModelProvidersFile) {
151.         const configuredDefaultModel = config.defaultModel;
152.         this._defaultModel = configuredDefaultModel;
153. 
154.         // Filter to providers whose credentials are actually available.
155.         // GitHub providers are kept even without an env token because a
156.         // per-user key may be supplied later from CMS, and the UX should
157.         // still show configured GitHub models. GitHub credential enforcement
158.         // happens when creating/resuming a GitHub-backed session.
159.         this.providers = config.providers.filter(p => {
160.             if (p.type === "github") {
161.                 return true;
162.             }
163.             return !!resolveEnvValue(p.apiKey);
164.         });
165. 
166.         // Build lookups
167.         for (const p of this.providers) {
168.             for (const m of p.models) {
169.                 const entry: ModelEntry = typeof m === "string" ? { name: m } : m;
170.                 const supportedReasoningEfforts = normalizeReasoningEfforts(entry.supportedReasoningEfforts);
171.                 const defaultReasoningEffort = supportedReasoningEfforts.includes(entry.defaultReasoningEffort as ReasoningEffort)
172.                     ? entry.defaultReasoningEffort
173.                     : undefined;
174.                 const supportedContextTiers = normalizeContextTiers(entry.supportedContextTiers);
175.                 // Default to the smaller window: an explicit valid default wins,
176.                 // otherwise "default" whenever tiers are offered at all.
177.                 const defaultContextTier = supportedContextTiers.length > 0
178.                     ? (supportedContextTiers.includes(entry.defaultContextTier as ContextTier)
179.                         ? entry.defaultContextTier
180.                         : "default")
181.                     : undefined;
182.                 const contextWindowSizes = normalizeContextWindowSizes(entry.contextWindowSizes, supportedContextTiers);
183.                 const qualified = `${p.id}:${entry.name}`;
184.                 const desc: ModelDescriptor = {
185.                     qualifiedName: qualified,
186.                     modelName: entry.name,
187.                     providerId: p.id,
188.                     providerType: p.type,
189.                     description: entry.description,
190.                     cost: entry.cost,
191.                     ...(supportedReasoningEfforts.length > 0 ? { supportedReasoningEfforts } : {}),
192.                     ...(defaultReasoningEffort ? { defaultReasoningEffort } : {}),
193.                     ...(supportedContextTiers.length > 0 ? { supportedContextTiers } : {}),
194.                     ...(defaultContextTier ? { defaultContextTier } : {}),
195.                     ...(Object.keys(contextWindowSizes).length > 0 ? { contextWindowSizes } : {}),
196.                 };
197.                 this.descriptors.set(qualified, desc);
198.                 this.qualifiedToProvider.set(qualified, p);
199.                 this._allDescriptors.push(desc);
200. 
201.                 // First provider to register a bare name wins
202.                 if (!this.bareToQualified.has(entry.name)) {
