215.                 availableSummary,
216.             );
217.         }
218. 
219.     }
220. 
221.     /** Default model in `provider:model` format. */
222.     get defaultModel(): string | undefined {
223.         return this._defaultModel;
224.     }
225. 
226.     /** All model descriptors across all providers. */
227.     get allModels(): ModelDescriptor[] {
228.         return [...this._allDescriptors];
229.     }
230. 
231.     /** All provider configs. */
