                     providerType: p.type,
                     description: entry.description,
                     cost: entry.cost,
                     ...(supportedReasoningEfforts.length > 0 ? { supportedReasoningEfforts } : {}),
                     ...(defaultReasoningEffort ? { defaultReasoningEffort } : {}),
